def compute(vars):
    values = {
        "2004": vars["v1"],
        "2005": vars["v2"],
        "2006": vars["v3"],
    }
    greatest = max(values.values())
    year = max(values, key=values.get)
    return {
        "value": greatest,
        "trace": {
            "provisions_by_year": values,
            "greatest_year": year,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
